// Count total topics
let totalNewTopics = 0;
for (const [trackId, topics] of Object.entries(ALL_EXPANDED_TRACKS)) {
  totalNewTopics += topics.length;
}
console.log(`Defined ${totalNewTopics} comprehensive topics across 20 tracks!`);

// Load subjectsCatalog.ts
const catalogPath = 'src/features/interview-docs/data/subjectsCatalog.ts';
let catalog = fs.readFileSync(catalogPath, 'utf-8');

// 1. Update totalTopicsCount in ALL_SUBJECTS_CATALOG for each track
for (const [trackId, topics] of Object.entries(ALL_EXPANDED_TRACKS)) {
  const count = topics.length;
  const regex = new RegExp(`(id:\\s*['"]${trackId}['"][\\s\\S]*?totalTopicsCount:\\s*)\\d+,`);
  catalog = catalog.replace(regex, `$1${count},`);
}
console.log('Updated totalTopicsCount across all tracks in ALL_SUBJECTS_CATALOG!');

// 2. Extract header (imports + ALL_SUBJECTS_CATALOG) up to TOPICS_BY_SUBJECT
const splitMarker = 'export const TOPICS_BY_SUBJECT: Record<SubjectId, TopicMetadata[]> = {';
const splitIndex = catalog.indexOf(splitMarker);
if (splitIndex === -1) {
  throw new Error('Could not find TOPICS_BY_SUBJECT marker in subjectsCatalog.ts');
}

const headerContent = catalog.slice(0, splitIndex) + splitMarker;

// Load HTML topics from htmlTrack.ts
const { HTML_TRACK_DOCS } = await import('../src/features/interview-docs/data/tracks/htmlTrack.ts');
console.log(`Loaded ${HTML_TRACK_DOCS.length} HTML topics from htmlTrack.ts`);

const htmlTopics = HTML_TRACK_DOCS.map((doc, idx) => ({
  id: doc.topicId,
  subjectId: 'html',
  title: doc.title,
  order: idx + 1,
  description: doc.description,
  subtopics: doc.sections.map(s => ({
    id: s.id,
    title: s.heading,
    conceptId: 'html_' + s.id.replace(/-/g, '_'),
  })),
}));

// Build clean TOPICS_BY_SUBJECT output
let newCatalogContent = `${headerContent}\n  "html": ${JSON.stringify(htmlTopics, null, 2)}`;

for (const [trackId, topics] of Object.entries(ALL_EXPANDED_TRACKS)) {
  const formattedTopics = topics.map((t, idx) => ({
    id: t.id,
    subjectId: trackId,
    title: t.title,
    order: idx + 1,
    description: t.desc,
    subtopics: [
      {
        id: `${t.id}-basics`,
        title: `What is ${t.title.split(':')[0]}?`,
        conceptId: `${trackId}_${t.id.replace(/-/g, '_')}_whatis`,
      },
      {
        id: `${t.id}-usage`,
        title: `Practical Usage & Code Examples`,
        conceptId: `${trackId}_${t.id.replace(/-/g, '_')}_usage`,
      },
      {
        id: `${t.id}-best-practices`,
        title: `Best Practices & Common Mistakes`,
        conceptId: `${trackId}_${t.id.replace(/-/g, '_')}_bestpractices`,
      },
    ],
  }));

  newCatalogContent += `,\n\n  "${trackId}": ${JSON.stringify(formattedTopics, null, 2)}`;
}

newCatalogContent += '\n};\n';

fs.writeFileSync(catalogPath, newCatalogContent, 'utf-8');
console.log(`Successfully generated subjectsCatalog.ts with all 100 HTML topics + ${totalNewTopics} track topics (${100 + totalNewTopics} total topics)!`);

